import{_ as t,o as c,c as o,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"UC 02 — Agency & Workspace (UC-014 – UC-039)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/02-agency-workspace.md","filePath":"ba/use-cases/02-agency-workspace.md"}'),a={name:"ba/use-cases/02-agency-workspace.md"};function i(d,e,r,l,s,g){return c(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="uc-02-—-agency-workspace-uc-014-–-uc-039" tabindex="-1">UC 02 — Agency &amp; Workspace (<code>UC-014</code> – <code>UC-039</code>) <a class="header-anchor" href="#uc-02-—-agency-workspace-uc-014-–-uc-039" aria-label="Permalink to &quot;UC 02 — Agency &amp; Workspace (`UC-014` – `UC-039`)&quot;">​</a></h1><p>&gt; <a href="./01-authentication-profile.html">&lt;&lt; 01-authentication-profile.md</a> | <a href="./README.html">UC Index</a> | <a href="./../03-agency-workspace.html">Domain BA Spec: 03-agency-workspace.md</a> | <a href="./03-media-package-campaign.html">03-media-package-campaign.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-26-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (26 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-26-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (26 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-014</code></td><td style="text-align:left;">List Agency</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.4.1</code></td><td style="text-align:left;"><code>BR-15, BR-16</code></td></tr><tr><td style="text-align:center;"><code>UC-015</code></td><td style="text-align:left;">View Agency Dashboard</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.2</code></td><td style="text-align:left;"><code>BR-15, BR-20</code></td></tr><tr><td style="text-align:center;"><code>UC-016</code></td><td style="text-align:left;">Create Agency</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.4.3</code></td><td style="text-align:left;"><code>BR-12, BR-15, BR-58</code></td></tr><tr><td style="text-align:center;"><code>UC-017</code></td><td style="text-align:left;">View Agency Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.4</code></td><td style="text-align:left;"><code>BR-15</code></td></tr><tr><td style="text-align:center;"><code>UC-018</code></td><td style="text-align:left;">Update Agency Profile</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.5</code></td><td style="text-align:left;"><code>BR-12, BR-15</code></td></tr><tr><td style="text-align:center;"><code>UC-019</code></td><td style="text-align:left;">Remove Agency</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.6</code></td><td style="text-align:left;"><code>BR-15, BR-16</code></td></tr><tr><td style="text-align:center;"><code>UC-020</code></td><td style="text-align:left;">Invite Agency Member</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.7</code></td><td style="text-align:left;"><code>BR-01, BR-15, BR-17</code></td></tr><tr><td style="text-align:center;"><code>UC-021</code></td><td style="text-align:left;">View Agency Invitation Status</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.8</code></td><td style="text-align:left;"><code>BR-17, BR-18</code></td></tr><tr><td style="text-align:center;"><code>UC-022</code></td><td style="text-align:left;">Accept Agency Invitation</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.9</code></td><td style="text-align:left;"><code>BR-17, BR-18</code></td></tr><tr><td style="text-align:center;"><code>UC-023</code></td><td style="text-align:left;">Decline Agency Invitation</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.10</code></td><td style="text-align:left;"><code>BR-17, BR-18</code></td></tr><tr><td style="text-align:center;"><code>UC-024</code></td><td style="text-align:left;">Remove Agency Member</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.11</code></td><td style="text-align:left;"><code>BR-15, BR-19, BR-21</code></td></tr><tr><td style="text-align:center;"><code>UC-025</code></td><td style="text-align:left;">List Workspace</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.12</code></td><td style="text-align:left;"><code>BR-15, BR-20</code></td></tr><tr><td style="text-align:center;"><code>UC-026</code></td><td style="text-align:left;">View Workspace Dashboard</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.13</code></td><td style="text-align:left;"><code>BR-20, BR-22</code></td></tr><tr><td style="text-align:center;"><code>UC-027</code></td><td style="text-align:left;">Create Workspace</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.14</code></td><td style="text-align:left;"><code>BR-12, BR-15, BR-21, BR-22, BR-58</code></td></tr><tr><td style="text-align:center;"><code>UC-028</code></td><td style="text-align:left;">View Workspace Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.15</code></td><td style="text-align:left;"><code>BR-20, BR-22</code></td></tr><tr><td style="text-align:center;"><code>UC-029</code></td><td style="text-align:left;">Update Workspace Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.4.16</code></td><td style="text-align:left;"><code>BR-12, BR-15, BR-21, BR-22</code></td></tr><tr><td style="text-align:center;"><code>UC-030</code></td><td style="text-align:left;">Delete Workspace</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.17</code></td><td style="text-align:left;"><code>BR-15, BR-16</code></td></tr><tr><td style="text-align:center;"><code>UC-031</code></td><td style="text-align:left;">Leave Workspace</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.18</code></td><td style="text-align:left;"><code>BR-21, BR-23</code></td></tr><tr><td style="text-align:center;"><code>UC-032</code></td><td style="text-align:left;">Save Workspace Template</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.19</code></td><td style="text-align:left;"><code>BR-15, BR-24</code></td></tr><tr><td style="text-align:center;"><code>UC-033</code></td><td style="text-align:left;">View Workspace Templates</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.20</code></td><td style="text-align:left;"><code>BR-15, BR-24</code></td></tr><tr><td style="text-align:center;"><code>UC-034</code></td><td style="text-align:left;">Apply Workspace Template</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.21</code></td><td style="text-align:left;"><code>BR-15, BR-22, BR-24</code></td></tr><tr><td style="text-align:center;"><code>UC-035</code></td><td style="text-align:left;">Delete Workspace Template</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.4.22</code></td><td style="text-align:left;"><code>BR-15, BR-24</code></td></tr><tr><td style="text-align:center;"><code>UC-036</code></td><td style="text-align:left;">View Workspace Members</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.4.23</code></td><td style="text-align:left;"><code>BR-20, BR-21</code></td></tr><tr><td style="text-align:center;"><code>UC-037</code></td><td style="text-align:left;">Add Workspace Member</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.4.24</code></td><td style="text-align:left;"><code>BR-13, BR-15, BR-20, BR-21</code></td></tr><tr><td style="text-align:center;"><code>UC-038</code></td><td style="text-align:left;">Update Workspace Member Role</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.4.25</code></td><td style="text-align:left;"><code>BR-15, BR-21</code></td></tr><tr><td style="text-align:center;"><code>UC-039</code></td><td style="text-align:left;">Remove Workspace Member</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.4.26</code></td><td style="text-align:left;"><code>BR-19, BR-20, BR-21</code></td></tr></tbody></table><hr><h2 id="uc-014-—-list-agency" tabindex="-1">UC-014 — List Agency <a class="header-anchor" href="#uc-014-—-list-agency" aria-label="Permalink to &quot;UC-014 — List Agency&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.1</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-16</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách toàn bộ các Agency mà người dùng đang sở hữu (tư cách Owner) hoặc đang tham gia làm thành viên chính thức trên màn hình Agency Directory (/agencies). Hỗ trợ tìm kiếm theo tên Agency, lọc theo vai trò (Owned / Joined) và hiển thị tóm tắt số lượng thành viên, số lượng Workspace đang hoạt động.</li></ul><hr><h2 id="uc-015-—-view-agency-dashboard" tabindex="-1">UC-015 — View Agency Dashboard <a class="header-anchor" href="#uc-015-—-view-agency-dashboard" aria-label="Permalink to &quot;UC-015 — View Agency Dashboard&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.2</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-20</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển tổng quan của công ty (Agency Dashboard — /agency/:id/dashboard). Hiển thị các chỉ số KPI toàn Agency: tổng số Workspace đang hoạt động, số thành viên, tiến độ các chiến dịch truyền thông (Media Campaigns), hiệu suất hoàn thành công việc theo tuần/tháng, và mức tiêu thụ hạn mức gói cước / AI Credit.</li></ul><hr><h2 id="uc-016-—-create-agency" tabindex="-1">UC-016 — Create Agency <a class="header-anchor" href="#uc-016-—-create-agency" aria-label="Permalink to &quot;UC-016 — Create Agency&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.3</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-12, BR-15, BR-58</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG22, MSG23</code></li><li><strong>Specification &amp; Flow:</strong> Khởi tạo một Agency mới trên màn hình Create Agency (/agencies/new). Người tạo bắt buộc nhập Tên công ty/Agency, Lĩnh vực hoạt động, Mô tả, Thông tin liên hệ và Logo (tùy chọn). Hệ thống kiểm tra giới hạn số lượng Agency theo gói đăng ký hiện tại (BR-58) và tự động gắn cứng owner_id của Agency với user_id của người khởi tạo duy nhất (vai trò OWNER, BR-15).</li></ul><hr><h2 id="uc-017-—-view-agency-profile" tabindex="-1">UC-017 — View Agency Profile <a class="header-anchor" href="#uc-017-—-view-agency-profile" aria-label="Permalink to &quot;UC-017 — View Agency Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.4</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-15</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem trang hồ sơ giới thiệu công ty (Agency Profile — /agency/:id/profile). Hiển thị thông tin đại diện chính thức của Agency (Tên công ty, Logo, Ảnh bìa, Giới thiệu năng lực, Lĩnh vực chuyên môn, Website, Email/Hotline liên hệ và các gói dịch vụ mẫu) để khách hàng (Client) tìm hiểu năng lực của Agency.</li></ul><hr><h2 id="uc-018-—-update-agency-profile" tabindex="-1">UC-018 — Update Agency Profile <a class="header-anchor" href="#uc-018-—-update-agency-profile" aria-label="Permalink to &quot;UC-018 — Update Agency Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.5</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-12, BR-15</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG21, MSG22</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật thông tin hồ sơ công ty (Agency Profile — /agency/:id/settings). Chỉ chủ sở hữu (Owner) mới có quyền chỉnh sửa Tên Agency, Mô tả giới thiệu, Website, Địa chỉ, Thông tin liên hệ và tải lên Logo/Banner mới (BR-15, BR-15).</li></ul><hr><h2 id="uc-019-—-remove-agency" tabindex="-1">UC-019 — Remove Agency <a class="header-anchor" href="#uc-019-—-remove-agency" aria-label="Permalink to &quot;UC-019 — Remove Agency&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.6</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-16</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG24</code></li><li><strong>Specification &amp; Flow:</strong> Xóa mềm công ty (Remove Agency) tại màn hình Agency Settings (/agency/:id/settings) kèm hộp thoại xác nhận tên Agency. Hệ thống chỉ thực hiện xóa mềm (chuyển trạng thái sang INACTIVE/DELETED_PENDING) và lưu giữ toàn bộ dữ liệu để Owner có thể khôi phục lại trong vòng 30 ngày trước khi hết hạn lưu trữ (BR-16); tạm khóa quyền truy cập vào các Workspace trực thuộc trong thời gian bị xóa mềm.</li></ul><hr><h2 id="uc-020-—-invite-agency-member" tabindex="-1">UC-020 — Invite Agency Member <a class="header-anchor" href="#uc-020-—-invite-agency-member" aria-label="Permalink to &quot;UC-020 — Invite Agency Member&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.7</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-15, BR-17</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG04, MSG07, MSG08, MSG25, MSG26</code></li><li><strong>Specification &amp; Flow:</strong> Mời thành viên mới gia nhập Agency thông qua địa chỉ Email và thông báo trên hệ thống (/agency/:id/members). Khi được mời vào cấp độ Agency, người dùng chỉ mang tư cách thành viên chung của công ty (Agency Member) chứ chưa gắn vai trò quản trị đặc thù (chỉ người sáng lập ban đầu mới có vai trò OWNER); lời mời tự động hết hạn sau 30 ngày (30 ngày, BR-17).</li></ul><hr><h2 id="uc-021-—-view-agency-invitation-status" tabindex="-1">UC-021 — View Agency Invitation Status <a class="header-anchor" href="#uc-021-—-view-agency-invitation-status" aria-label="Permalink to &quot;UC-021 — View Agency Invitation Status&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.8</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-17, BR-18</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Theo dõi danh sách và trạng thái các lời mời tham gia Agency (PENDING, ACCEPTED, DECLINED, EXPIRED) kèm thời gian đếm ngược hết hạn 30 ngày (30 ngày, BR-17). Cả người gửi lời mời (Owner) và người nhận lời mời đều có thể xem trạng thái; Owner có thể gửi lại (Resend) hoặc thu hồi lời mời đang ở trạng thái PENDING.</li></ul><hr><h2 id="uc-022-—-accept-agency-invitation" tabindex="-1">UC-022 — Accept Agency Invitation <a class="header-anchor" href="#uc-022-—-accept-agency-invitation" aria-label="Permalink to &quot;UC-022 — Accept Agency Invitation&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.9</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-17, BR-18</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG27, MSG28</code></li><li><strong>Specification &amp; Flow:</strong> Chấp nhận lời mời tham gia Agency từ thông báo trong ứng dụng hoặc liên kết trong email (/invitations/:token). Hệ thống kiểm tra lời mời còn ở trạng thái PENDING và chưa quá hạn 30 ngày (BR-17), chuyển trạng thái lời mời sang ACCEPTED và thêm người dùng vào danh sách thành viên chính thức của Agency.</li></ul><hr><h2 id="uc-023-—-decline-agency-invitation" tabindex="-1">UC-023 — Decline Agency Invitation <a class="header-anchor" href="#uc-023-—-decline-agency-invitation" aria-label="Permalink to &quot;UC-023 — Decline Agency Invitation&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.10</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-17, BR-18</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG27, MSG28</code></li><li><strong>Specification &amp; Flow:</strong> Từ chối lời mời tham gia Agency (/invitations/:token). Hệ thống kiểm tra lời mời đang ở trạng thái PENDING (BR-17), cập nhật trạng thái lời mời sang DECLINED và gửi thông báo phản hồi cho Owner.</li></ul><hr><h2 id="uc-024-—-remove-agency-member" tabindex="-1">UC-024 — Remove Agency Member <a class="header-anchor" href="#uc-024-—-remove-agency-member" aria-label="Permalink to &quot;UC-024 — Remove Agency Member&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.11</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-19, BR-21</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG29, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xóa thành viên khỏi Agency (/agency/:id/members). Sau khi bị xóa, người dùng lập tức mất quyền truy cập vào Agency và toàn bộ các Workspace trực thuộc; tuy nhiên mọi tài nguyên, bài viết, tư liệu và lịch sử công việc mà người đó đã tạo ra vẫn được bảo toàn nguyên vẹn vì thuộc tài sản chung của Agency. Nếu sau này được mời quay lại, họ có thể tiếp tục sử dụng và chỉnh sửa các tài nguyên được phân quyền (BR-19).</li></ul><hr><h2 id="uc-025-—-list-workspace" tabindex="-1">UC-025 — List Workspace <a class="header-anchor" href="#uc-025-—-list-workspace" aria-label="Permalink to &quot;UC-025 — List Workspace&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.12</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-20</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách các Workspace trong Agency (/agency/:id/workspaces). Owner nhìn thấy toàn bộ tất cả các Workspace của công ty; các vai trò khác (Manager, Creator, Client) chỉ nhìn thấy các Workspace mà mình được gán làm thành viên (BR-20).</li></ul><hr><h2 id="uc-026-—-view-workspace-dashboard" tabindex="-1">UC-026 — View Workspace Dashboard <a class="header-anchor" href="#uc-026-—-view-workspace-dashboard" aria-label="Permalink to &quot;UC-026 — View Workspace Dashboard&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.13</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-22</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển tổng quan của từng Workspace (Workspace Dashboard — /workspaces/:id/dashboard). Hiển thị thống kê tiến độ công việc theo trạng thái (Backlog, In Progress, In Review, Approved, Published), lịch đăng bài sắp tới, tiến độ chiến dịch truyền thông và lượng AI Credit đã sử dụng của Workspace.</li></ul><hr><h2 id="uc-027-—-create-workspace" tabindex="-1">UC-027 — Create Workspace <a class="header-anchor" href="#uc-027-—-create-workspace" aria-label="Permalink to &quot;UC-027 — Create Workspace&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.14</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-12, BR-15, BR-21, BR-22, BR-58</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG22, MSG23, MSG48</code></li><li><strong>Specification &amp; Flow:</strong> Tạo mới một Workspace trực thuộc Agency (/agency/:id/workspaces/new). Khi khởi tạo Workspace, Owner bắt buộc phải chọn và gán ít nhất 01 thành viên của Agency làm Manager (người chịu trách nhiệm quản lý toàn bộ vận hành trong Workspace đó, BR-21), đồng thời cấu hình Tên Workspace, Mô tả, Múi giờ chuẩn (Timezone Configuration, BR-22) và liên kết gói truyền thông mẫu ban đầu.</li></ul><hr><h2 id="uc-028-—-view-workspace-profile" tabindex="-1">UC-028 — View Workspace Profile <a class="header-anchor" href="#uc-028-—-view-workspace-profile" aria-label="Permalink to &quot;UC-028 — View Workspace Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.15</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-22</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem thông tin cấu hình chi tiết của Workspace (Workspace Profile — /workspaces/:id/settings). Hiển thị Tên Workspace, Mô tả dự án/nhãn hàng, Thông tin Client liên kết, Trạng thái hoạt động, và đặc biệt là trường cấu hình Múi giờ chuẩn (Timezone Configuration theo chuẩn IANA UTC offset, BR-22) giúp đồng bộ lịch đăng bài viral theo đúng khu vực địa lý của chiến dịch truyền thông.</li></ul><hr><h2 id="uc-029-—-update-workspace-profile" tabindex="-1">UC-029 — Update Workspace Profile <a class="header-anchor" href="#uc-029-—-update-workspace-profile" aria-label="Permalink to &quot;UC-029 — Update Workspace Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.16</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-12, BR-15, BR-21, BR-22</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG21, MSG22</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật thông tin hồ sơ Workspace (/workspaces/:id/settings). Cho phép chỉnh sửa Tên Workspace, Mô tả, Ảnh đại diện Workspace và cập nhật trường Múi giờ chuẩn (Timezone Configuration, BR-22) để tự động quy đổi mốc thời gian lên lịch đăng bài và hạn chót công việc.</li></ul><hr><h2 id="uc-030-—-delete-workspace" tabindex="-1">UC-030 — Delete Workspace <a class="header-anchor" href="#uc-030-—-delete-workspace" aria-label="Permalink to &quot;UC-030 — Delete Workspace&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.17</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-16</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG24, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xóa mềm Workspace (/workspaces/:id/settings). Chỉ duy nhất Owner mới có quyền xóa Workspace. Khi xóa, toàn bộ dữ liệu bên trong chuyển sang trạng thái INACTIVE, các thành viên không còn quyền truy cập, nhưng dữ liệu được bảo lưu và Owner có thể khôi phục lại hoàn toàn trong vòng 30 ngày (BR-16).</li></ul><hr><h2 id="uc-031-—-leave-workspace" tabindex="-1">UC-031 — Leave Workspace <a class="header-anchor" href="#uc-031-—-leave-workspace" aria-label="Permalink to &quot;UC-031 — Leave Workspace&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.18</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-21, BR-23</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG29, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Rời khỏi một Workspace cụ thể (/workspaces/:id/settings). Thành viên rời khỏi Workspace sẽ không còn quyền truy cập vào Workspace đó nữa nhưng vẫn giữ nguyên tư cách là thành viên của Agency chủ quản (BR-23). Nếu người rời đi là Manager duy nhất còn lại thì hệ thống yêu cầu bổ nhiệm Manager thay thế trước khi rời (BR-21).</li></ul><hr><h2 id="uc-032-—-save-workspace-template" tabindex="-1">UC-032 — Save Workspace Template <a class="header-anchor" href="#uc-032-—-save-workspace-template" aria-label="Permalink to &quot;UC-032 — Save Workspace Template&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.19</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-24</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG30</code></li><li><strong>Specification &amp; Flow:</strong> Lưu cấu hình của một Workspace hiện hành thành Mẫu triển khai (Save Workspace Template — /workspaces/:id/settings). Lưu lại các thông tin cấu trúc chuẩn (Múi giờ mặc định, danh mục công việc mẫu, bộ sưu tập hashtag mẫu, mẫu email và cấu hình quy trình duyệt) thành các Template khác nhau để tái sử dụng nhanh cho các dự án sau (BR-24).</li></ul><hr><h2 id="uc-033-—-view-workspace-templates" tabindex="-1">UC-033 — View Workspace Templates <a class="header-anchor" href="#uc-033-—-view-workspace-templates" aria-label="Permalink to &quot;UC-033 — View Workspace Templates&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.20</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-24</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách và chi tiết các mẫu cấu hình Workspace (View Workspace Templates — /agency/:id/workspace-templates). Hiển thị cả các mẫu mặc định của hệ thống và các mẫu riêng do Agency đã lưu, bao gồm mô tả cấu trúc công việc, múi giờ và các thiết lập đi kèm (BR-24).</li></ul><hr><h2 id="uc-034-—-apply-workspace-template" tabindex="-1">UC-034 — Apply Workspace Template <a class="header-anchor" href="#uc-034-—-apply-workspace-template" aria-label="Permalink to &quot;UC-034 — Apply Workspace Template&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.21</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-22, BR-24</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG30, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Áp dụng một mẫu cấu hình Workspace đã lưu vào Workspace mới hoặc hiện hành (Apply Workspace Template). Hệ thống tự động khởi tạo nhanh các thiết lập múi giờ, danh mục mẫu công việc, bộ hashtag và mẫu email từ Template vào Workspace đích mà không làm ảnh hưởng đến dữ liệu lịch sử (BR-24).</li></ul><hr><h2 id="uc-035-—-delete-workspace-template" tabindex="-1">UC-035 — Delete Workspace Template <a class="header-anchor" href="#uc-035-—-delete-workspace-template" aria-label="Permalink to &quot;UC-035 — Delete Workspace Template&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.22</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-24</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG30, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xóa mẫu cấu hình Workspace do Agency tự tạo khỏi thư viện mẫu (/agency/:id/workspace-templates). Việc xóa Template không làm ảnh hưởng đến các Workspace đã được áp dụng mẫu đó trước đây (BR-24).</li></ul><hr><h2 id="uc-036-—-view-workspace-members" tabindex="-1">UC-036 — View Workspace Members <a class="header-anchor" href="#uc-036-—-view-workspace-members" aria-label="Permalink to &quot;UC-036 — View Workspace Members&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.23</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-21</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách các thành viên đang tham gia trong Workspace (/workspaces/:id/members). Hiển thị Họ tên, Email, Ảnh đại diện, Vai trò trong Workspace (<code>Manager</code>, <code>Creator</code>, <code>Client</code> — cùng <code>Owner</code> của Agency), Ngày tham gia và trạng thái hoạt động.</li></ul><hr><h2 id="uc-037-—-add-workspace-member" tabindex="-1">UC-037 — Add Workspace Member <a class="header-anchor" href="#uc-037-—-add-workspace-member" aria-label="Permalink to &quot;UC-037 — Add Workspace Member&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.24</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-13, BR-15, BR-20, BR-21</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG26, MSG29</code></li><li><strong>Specification &amp; Flow:</strong> Thêm thành viên thuộc Agency (hoặc tài khoản Client) vào trong Workspace và gán vai trò cụ thể (MANAGER, CREATOR hoặc CLIENT — /workspaces/:id/members). Hệ thống kiểm tra người được thêm phải thuộc Agency (hoặc là Client đối tác) và chưa tồn tại trong Workspace (BR-20).</li></ul><hr><h2 id="uc-038-—-update-workspace-member-role" tabindex="-1">UC-038 — Update Workspace Member Role <a class="header-anchor" href="#uc-038-—-update-workspace-member-role" aria-label="Permalink to &quot;UC-038 — Update Workspace Member Role&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.25</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-21</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG29, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật vai trò (Role) của thành viên trong Workspace (ví dụ chuyển đổi giữa CREATOR và MANAGER — /workspaces/:id/members). Hệ thống kiểm tra ràng buộc luôn phải duy trì ít nhất 01 Manager đang hoạt động trong mỗi Workspace (BR-21, BR-21).</li></ul><hr><h2 id="uc-039-—-remove-workspace-member" tabindex="-1">UC-039 — Remove Workspace Member <a class="header-anchor" href="#uc-039-—-remove-workspace-member" aria-label="Permalink to &quot;UC-039 — Remove Workspace Member&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.4.26</code> (3.4 Agency &amp; Workspace)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-19, BR-20, BR-21</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG29, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xóa thành viên ra khỏi Workspace (/workspaces/:id/members). Thành viên bị xóa khỏi Workspace không còn truy cập được dữ liệu của Workspace đó nhưng các công việc/tư liệu họ đã đóng góp vẫn được giữ lại, và họ vẫn là thành viên của Agency (BR-19, BR-21, BR-21).</li></ul>',83)])])}const u=t(a,[["render",i]]);export{p as __pageData,u as default};
